insert into auth.users(id,email) values ('00000000-0000-4000-a000-00000000000a','guard-owner@test.invalid');
insert into results values ('create', public.save_session('{"ref":"30000000-0000-4000-a000-000000000001","performed_on":"2026-10-31","title":"Original","sets":[{"exercise_name":"Bench","load":30,"unit":"kg","reps":7}]}'::jsonb));
insert into results values ('missing', public.save_session('{"ref":"30000000-0000-4000-a000-000000000001","performed_on":"2026-10-31","title":"Overwrite","sets":[]}'::jsonb));
insert into tap(line) select is((select value->>'status' from results where key='missing'), 'conflict', 'missing revision conflicts');
insert into tap(line) select is((select title from workout_sessions), 'Original', 'missing revision leaves session intact');
insert into results values ('stale', public.save_session('{"ref":"30000000-0000-4000-a000-000000000001","performed_on":"2026-10-31","title":"Overwrite","sets":[]}'::jsonb || jsonb_build_object('expected_revision', (select (value->>'revision')::bigint from results where key='create'))));
insert into tap(line) select is((select value->>'status' from results where key='stale'), 'conflict', 'stale revision conflicts');
insert into tap(line) select is((select reps from session_sets), 8, 'stale save preserves newer set');
insert into results values ('current', public.save_session('{"ref":"30000000-0000-4000-a000-000000000001","performed_on":"2026-10-31","title":"Updated","sets":[]}'::jsonb || jsonb_build_object('expected_revision', (select revision from workout_sessions))));
insert into tap(line) select is((select value->>'title' from results where key='current'), 'Updated', 'current revision applies');
insert into tap(line) select is((select count(*) from session_sets), 0::bigint, 'current revision replaces sets');
insert into results values ('deleted', public.save_session('{"ref":"30000000-0000-4000-a000-000000000001","performed_on":"2026-10-31","sets":[]}'::jsonb || jsonb_build_object('expected_revision', (select (value->>'revision')::bigint from results where key='current'))));
insert into tap(line) select is((select value->>'status' from results where key='deleted'), 'conflict', 'update after deletion conflicts');
insert into tap(line) select is((select count(*) from workout_sessions), 0::bigint, 'update after deletion does not recreate');
insert into results values ('phone_deleted', public.push_session('{"id":"30000000-0000-4000-a000-000000000001","performed_on":"2026-10-31","sets":[]}'::jsonb, 1, 1));
insert into tap(line) select is((select value->>'status' from results where key='phone_deleted'), 'conflict', 'phone push after deletion conflicts');
insert into tap(line) select is((select value->'session' from results where key='phone_deleted'), 'null'::jsonb, 'deleted conflict returns no server session');
insert into tap(line) select * from finish();
